import pathlibimport peeweefrom playhouse.sqlite_ext import SqliteExtDatabase#Создание БД и создание peewee моделейdatabase = SqliteExtDatabase(    str(pathlib.Path(".").joinpath(".im-generation-db.sqlite")),    regexp_function=True,    pragmas={"journal_mode": "wal", "cache_size": -1024 * 64},)class BaseModel(peewee.Model):    class Meta:        database = databaseclass AccountStentorInfo(BaseModel):    account_stentor = peewee.TextField()class AccountInfo(BaseModel):    account = peewee.TextField()class ChatInfo(BaseModel):    account = peewee.ForeignKeyField(AccountInfo, backref='chats')    chat_id = peewee.TextField()class MessageInfo(BaseModel):    chat = peewee.ForeignKeyField(ChatInfo, backref='messages')    message_id = peewee.TextField()class ThreadInfo(BaseModel):    message = peewee.ForeignKeyField(MessageInfo, backref='threads')    thread_id = peewee.TextField()class AttachmentInfo(BaseModel):    account = peewee.ForeignKeyField(AccountInfo, backref='attachs')    attach_id = peewee.TextField()class AttachmentThreadInfo(BaseModel):    thread = peewee.ForeignKeyField(ThreadInfo, backref='attachs_threads')    attach_thread_id = peewee.TextField()database.create_tables([AccountInfo, ChatInfo, MessageInfo, ThreadInfo, AttachmentInfo, AttachmentThreadInfo, AccountStentorInfo])